<script setup lang="ts">
import {ref} from 'vue'
import {command,message} from '../api'
import {date} from '../format'
interface Hidden{id:number;name:string;birthdate:string;revision:number}
interface Audit{id:number;action:string;entityId:number|null;actor:string;createdAt:string}
const hidden=ref<Hidden[]>([]),audit=ref<Audit[]>([]),hiddenOpen=ref(false),auditOpen=ref(false),error=ref(''),busy=ref(false)
async function showHidden(){try{hidden.value=await command('hidden_patients');hiddenOpen.value=true}catch(e){error.value=message(e)}}
async function restorePatient(patient:Hidden){busy.value=true;try{await command('set_patient_hidden',{id:patient.id,revision:patient.revision,hidden:false});await showHidden()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function showAudit(){try{audit.value=await command('list_audit');auditOpen.value=true}catch(e){error.value=message(e)}}
const actions:Record<string,string>={cleanup_empty_orphans:'Удаление пустых заготовок',login:'Вход',setup_admin:'Первый администратор',save_user:'Учётная запись',save_patient:'Карточка пациента',save_study:'Исследование',restore:'Восстановление базы',link_orphan:'Привязка записи',hide_patient:'Скрытие карточки',restore_patient:'Возврат карточки',create_bundle:'Объединённая печать',attach_file:'Вложение',hide_attachment:'Скрытие вложения',create_doctor:'Новый врач'}
</script>
<template><section class="settings-section"><h2>Архив и журнал</h2><div class="flex flex-wrap gap-3 mt-5"><UButton variant="outline" @click="showHidden">Скрытые карточки</UButton><UButton variant="outline" @click="showAudit">Журнал действий</UButton></div><UAlert v-if="error" color="error" variant="soft" :description="error" class="mt-5"/><UModal v-model:open="hiddenOpen" title="Скрытые карточки" description="Возврат карточки сохраняет её историю" :ui="{content:'max-w-[900px]'}"><template #body><div class="table-scroll"><table class="patient-table"><thead><tr><th>Пациент</th><th>Дата рождения</th><th>Действие</th></tr></thead><tbody><tr v-for="p in hidden" :key="p.id"><td>{{p.name}} · № {{p.id}}</td><td>{{date(p.birthdate)}}</td><td><UButton variant="outline" :disabled="busy" @click="restorePatient(p)">Вернуть в список</UButton></td></tr></tbody></table><p v-if="!hidden.length">Скрытых карточек нет</p></div></template></UModal><UModal v-model:open="auditOpen" title="Журнал действий" description="Последние 300 действий. Пароли в журнал не записываются." :ui="{content:'max-w-[1100px]'}"><template #body><div class="table-scroll"><table class="patient-table"><thead><tr><th>Время UTC</th><th>Пользователь</th><th>Действие</th><th>Запись</th></tr></thead><tbody><tr v-for="item in audit" :key="item.id"><td>{{item.createdAt}}</td><td>{{item.actor||(item.action==='cleanup_empty_orphans'?'Система':'Не указан')}}</td><td>{{actions[item.action]||item.action}}</td><td>{{item.entityId||'—'}}</td></tr></tbody></table></div></template></UModal></section></template>
